            [CiVariable("CI_TRIGGER_SHORT_TOKEN")]
            [GitLabCiVariableCategoryAttribute(GitLabCiVariableCategory.PREDEFINED)]
            public static string? ShortToken => CiEnvironment.GetRawValue("CI_TRIGGER_SHORT_TOKEN");
        }
    }
